{"code": "import os
from pathlib import Path

def walk(root):
    out, stack = [], [root]
    while stack:
        d = stack.pop()
        for name in sorted(os.listdir(d)):
            full = d + '/' + name
            if Path(full).is_dir():
                stack.append(full)
            else:
                out.append(full)
    return sorted(out)

files = walk('/repo')
for f in files:
    print(f)"}

