# Search all .py files for "dropout" (case-insensitive)
files = ['/repo/model.py', '/repo/train.py', '/repo/sample.py', '/repo/bench.py', '/repo/configurator.py']
files += [f'/repo/config/{n}' for n in os.listdir('/repo/config')]

for f in files:
    try:
        content = open(f).read()
        lines = content.split('\n')
        for i, line in enumerate(lines, 1):
            if re.search(r'dropout', line, re.IGNORECASE):
                print(f"{f}:{i}: {line.strip()}")
    except Exception as e:
        print(f"ERROR {f}: {e}")"}

